# -------------------- Advanced Analysis Features --------------------

class AdvancedPaperAnalyzer:
    """
    Enhanced analysis engine with:
    - TF-IDF based keyword extraction
    - Citation graph analysis (if available)
    - Trend detection across multiple papers
    - Methodology taxonomy classification
    """

    def __init__(self):
        self.vectorizer = TfidfVectorizer(
            max_features=1000,
            stop_words='english',
            ngram_range=(1, 3)
        )
        self._load_taxonomy()

    def _load_taxonomy(self):
        """Load methodology taxonomy for classification."""
        self.taxonomy = {
            'deep_learning': ['transformer', 'attention', 'cnn', 'rnn', 'lstm', 'gru', 'gan', 'vae', 'diffusion'],
            'reinforcement_learning': ['rl', 'reinforcement learning', 'q-learning', 'policy gradient', 'ppo', 'dqn'],
            'nlp': ['language model', 'bert', 'gpt', 't5', 'llama', 'tokenization', 'embedding'],
            'computer_vision': ['image', 'vision', 'object detection', 'segmentation', 'classification', 'yolo', 'resnet'],
            'optimization': ['gradient descent', 'adam', 'sgd', 'optimizer', 'learning rate', 'convergence'],
            'probabilistic': ['bayesian', 'gaussian process', 'variational inference', 'mcmc', 'monte carlo'],
            'graph': ['graph neural', 'gnn', 'graph convolution', 'node embedding', 'graph attention'],
            'generative': ['generative', 'synthesis', 'generation', 'sampling', 'latent', 'diffusion']
        }

    def classify_methodology(self, abstract: str) -> Dict[str, float]:
        """
        Classify the paper's methodology into taxonomy categories with confidence scores.
        
        Returns:
            Dictionary mapping category names to confidence scores (0-1)
        """
        if not abstract:
            return {}
        
        abstract_lower = abstract.lower()
        scores = {}
        
        for category, keywords in self.taxonomy.items():
            matches = sum(1 for kw in keywords if kw in abstract_lower)
            scores[category] = min(1.0, matches / max(len(keywords) * 0.1, 1))
        
        # Normalize
        total = sum(scores.values())
        if total > 0:
            scores = {k: v/total for k, v in scores.items()}
        
        return dict(sorted(scores.items(), key=lambda x: x[1], reverse=True))

    def extract_keywords_tfidf(self, abstracts: List[str], top_n: int = 20) -> List[Tuple[str, float]]:
        """
        Extract top keywords across multiple abstracts using TF-IDF.
        
        Args:
            abstracts: List of paper abstracts
            top_n: Number of top keywords to return
        
        Returns:
            List of (keyword, score) tuples
        """
        if not abstracts:
            return []
        
        try:
            tfidf_matrix = self.vectorizer.fit_transform(abstracts)
            feature_names = self.vectorizer.get_feature_names_out()
            
            # Aggregate scores across all documents
            avg_scores = np.array(tfidf_matrix.mean(axis=0)).flatten()
            
            # Get top N keywords
            top_indices = avg_scores.argsort()[-top_n:][::-1]
            keywords = [(feature_names[i], float(avg_scores[i])) for i in top_indices]
            
            return keywords
        except Exception as e:
            logger.error(f"TF-IDF keyword extraction failed: {e}")
            return []

    def detect_trends(self, papers: List[PaperMetadata], window_months: int = 3) -> Dict[str, float]:
        """
        Detect trending topics/methods in a set of papers over time.
        
        Args:
            papers: List of papers with timestamps
            window_months: Time window for trend detection
        
        Returns:
            Dictionary mapping trend terms to growth rates
        """
        if not papers:
            return {}
        
        # Sort papers by date
        sorted_papers = sorted(papers, key=lambda p: p.published)
        
        # Split into recent and older windows
        cutoff_date = datetime.utcnow() - timedelta(days=window_months * 30)
        recent_papers = [p for p in sorted_papers if p.published >= cutoff_date]
        older_papers = [p for p in sorted_papers if p.published < cutoff_date]
        
        if not recent_papers or not older_papers:
            return {}
        
        # Extract keywords from both groups
        recent_keywords = self._extract_frequent_terms([p.abstract for p in recent_papers])
        older_keywords = self._extract_frequent_terms([p.abstract for p in older_papers])
        
        # Compute growth rates
        trends = {}
        for term, recent_count in recent_keywords.items():
            older_count = older_keywords.get(term, 0)
            if older_count > 0:
                growth_rate = (recent_count - older_count) / older_count
                trends[term] = round(growth_rate, 4)
            else:
                trends[term] = 1.0  # New term, high growth
        
        return dict(sorted(trends.items(), key=lambda x: x[1], reverse=True)[:20])

    def _extract_frequent_terms(self, texts: List[str], top_n: int = 50) -> Dict[str, int]:
        """Extract most frequent meaningful terms from a list of texts."""
        if not texts:
            return {}
        
        # Simple tokenization and frequency counting
        all_terms = []
        for text in texts:
            if not text:
                continue
            # Extract meaningful n-grams (1-3 words)
            words = re.findall(r'\b[a-z]{3,}\b', text.lower())
            all_terms.extend(words)
            
            # Bigrams
            bigrams = [' '.join(words[i:i+2]) for i in range(len(words)-1)]
            all_terms.extend(bigrams)
        
        counter = Counter(all_terms)
        return dict(counter.most_common(top_n))

    def compute_similarity_matrix(self, papers: List[PaperMetadata]) -> np.ndarray:
        """
        Compute pairwise similarity matrix for a list of papers based on abstracts.
        
        Returns:
            NxN numpy array of cosine similarity scores
        """
        if not papers:
            return np.array([])
        
        abstracts = [p.abstract for p in papers]
        try:
            tfidf_matrix = self.vectorizer.fit_transform(abstracts)
            similarity_matrix = cosine_similarity(tfidf_matrix)
            return similarity_matrix
        except Exception as e:
            logger.error(f"Similarity computation failed: {e}")
            return np.array([])

# -------------------- Integration with Pipeline --------------------

class EnhancedPaperAnalyzer(PaperAnalyzer):
    """
    Enhanced version of PaperAnalyzer with advanced features.
    Extends the base analyzer with taxonomy classification and trend detection.
    """

    def __init__(self, config: ResearchPipelineConfig):
        super().__init__(config)
        self.advanced_analyzer = AdvancedPaperAnalyzer()

    async def analyze_paper(self, paper: PaperMetadata, query_context: str = "") -> AnalysisResult:
        """Enhanced analysis with taxonomy classification."""
        # Base analysis
        result = await super().analyze_paper(paper, query_context)
        
        # Add taxonomy classification
        taxonomy_scores = self.advanced_analyzer.classify_methodology(paper.abstract)
        result.key_methods.extend([
            f"{category} ({score:.2f})" 
            for category, score in taxonomy_scores.items() 
            if score > 0.1
        ])
        
        return result

# -------------------- Standalone Usage --------------------

async def analyze_papers_batch(
    papers: List[PaperMetadata],
    config: Optional[ResearchPipelineConfig] = None
) -> List[AnalysisResult]:
    """
    Batch analyze multiple papers with advanced features.
    
    Args:
        papers: List of papers to analyze
        config: Optional pipeline configuration
    
    Returns:
        List of AnalysisResult objects
    """
    config = config or ResearchPipelineConfig()
    analyzer = EnhancedPaperAnalyzer(config)
    
    results = []
    for paper in papers:
        result = await analyzer.analyze_paper(paper)
        results.append(result)
    
    return results

